import { Box, Stack } from "@mui/material";

import ForecastContextBar from "../../../components/layout/ForecastContextBar";

import ForecastOverview from "../components/ForecastOverview";
import ExportForecast from "../components/ExportForecast";

import { useForecastContext } from "../../../contexts/ForecastContext";
import { ForecastFilters } from "../types/forecast.types";

/**
 * =====================================================
 * FORECAST PAGE  (REDESIGNED)
 * =====================================================
 * Rebuilt page shell: a compact action row (Export CSV) on top of
 * the forecast context strip, followed by the fully regrouped
 * ForecastOverview. All panels read from the shared ForecastContext
 * so filtering stays in sync.
 */
const ForecastPage = () => {
  const { horizon, metric, entityId, scenario } = useForecastContext();
  const filters: ForecastFilters = { horizon, metric, entityId, scenario };

  return (
    <Box sx={{ width: "100%", minHeight: "100%", boxSizing: "border-box" }}>
      <Stack spacing={3}>
        {/* Action row */}
        <Box sx={{ display: "flex", justifyContent: "flex-end" }}>
          <ExportForecast filters={filters} />
        </Box>

        {/* Context strip */}
        <ForecastContextBar />

        {/* Main overview */}
        <ForecastOverview />
      </Stack>
    </Box>
  );
};

export default ForecastPage;
